  $('roles-list').replaceChildren();for(const role of Object.values(management.roles).sort((a,b)=>(['administrator','adult','child'].indexOf(a.id)+4)%4-(['administrator','adult','child'].indexOf(b.id)+4)%4||a.name.localeCompare(b.name))){const row=document.createElement('article');row.className='gs-profile-row';const actions=document.createElement('div');actions.className='gs-profile-row-actions';actions.append(button('Edit',()=>editRole(role)));if(!builtins.has(role.id))actions.append(iconButton('Remove '+role.name,()=>confirmRemove('Remove '+role.name+'?',{operation:'deleteRole',role:{id:role.id}}),'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',true));row.append(roleBadge(role.id),actions);$('roles-list').append(row);}
  $('groups-list').replaceChildren();const groupOrder=['g-guardians','g-adults','g-children'];for(const group of Object.values(management.profileGroups||{}).sort((a,b)=>(groupOrder.indexOf(a.id)+4)%4-(groupOrder.indexOf(b.id)+4)%4||a.name.localeCompare(b.name))){const row=document.createElement('article');row.className='gs-profile-row';const name=document.createElement('strong');name.textContent=group.name;name.dataset.tooltip='Group: '+group.roles.map(roleName).join(', ');const actions=document.createElement('div');actions.className='gs-profile-row-actions';actions.append(button('Edit',()=>editGroup(group)),iconButton('Remove '+group.name,()=>confirmRemove('Remove '+group.name+'?',{operation:'deleteGroup',group:{id:group.id}}),'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',true));if(group.id==='g-guardians')actions.lastElementChild.remove();else if(management.groupDefaults?.[group.id])actions.lastElementChild.remove();name.dataset.role=group.roles.map(roleTone).find(Boolean)||'';row.append(name,actions);$('groups-list').append(row);}syncManagement();
