   for(const role of Object.values(management.roles)){if(role.id==='administrator'&&!locked)continue;const row=choice('',role.id,group?.roles.includes(role.id)||false);row.append(roleBadge(role.id));$('group-role-choices').append(row);}
   for(const p of management.profiles){const row=choice('',p.id,group?p.groups?.includes(group.id)||false:false),input=row.querySelector('input'),caption=document.createElement('span'),name=document.createElement('strong');row.classList.add('gs-group-member');name.textContent=p.nickname;caption.className='gs-group-member-caption';caption.append(name,roleBadges(p.effectiveRoles||p.roles,p));row.replaceChildren(avatarImage(p.avatar),input,caption);input.disabled=p.usesGuardianPIN;row.dataset.tooltip=p.usesGuardianPIN?'Guardian profiles are assigned through Manage Guardians.':'';$('group-member-choices').append(row);}
