  function cancelGroupRole(){if(pendingGroupRole){pendingGroupRole.checked=false;pendingGroupRole=null;syncGroupAdmin();}}
  $('group-role-choices').addEventListener('change',event=>{const input=event.target;if(input.checked){for(const other of $('group-role-choices').querySelectorAll('input'))if(other!==input)other.checked=false;$('group-admin-ack').checked=false;if(rolesGrantAdmin([input.value])){pendingGroupRole=input;openModal($('group-admin-dialog'));}}syncGroupAdmin();});
  $('group-admin-confirm').addEventListener('click',()=>{pendingGroupRole=null;$('group-admin-ack').checked=true;$('group-admin-dialog').close();});
  for(const id of ['group-admin-close','group-admin-cancel'])$(id).addEventListener('click',()=>{cancelGroupRole();$('group-admin-dialog').close();});$('group-admin-dialog').addEventListener('cancel',cancelGroupRole);closeOnBackdropClick($('group-admin-dialog'),cancelGroupRole);
  $('group-name').addEventListener('input',syncGroupReset);$('group-reset').addEventListener('click',()=>confirmRemove('Reset '+editingGroup.name+' to its original defaults?',{operation:'resetGroup',group:{id:editingGroup.id}}));
