  $('group-editor-save').addEventListener('click',async()=>{const save=$('group-editor-save');save.disabled=true;try{const roles=[...$('group-role-choices').querySelectorAll('input:checked')].map(n=>n.value);if(!roles.length)throw Error('Choose a role for this group.');if(editingGroup?.id!=='g-guardians'&&rolesGrantAdmin(roles)&&!$('group-admin-ack').checked){pendingGroupRole=null;openModal($('group-admin-dialog'));return;}const group={id:editingGroup?.id||'',name:$('group-name').value.trim(),roles,libraryPolicy:editingGroup?.id==='g-guardians'?'':$('group-library-policy').value,libraries:editingGroup?.id==='g-guardians'?[]:[...groupLibraries]},members=[...$('group-member-choices').querySelectorAll('input:checked')].map(n=>n.value);await post({operation:'group',group,members,acknowledgeAdmin:$('group-admin-ack').checked});await reloadManagement();$('group-editor-dialog').close();showNotification('Group saved. Active profile sessions must sign in again.');}catch(error){notifyError(error);}finally{save.disabled=false;}});
  for(const id of ['group-editor-close','group-editor-cancel'])$(id).addEventListener('click',()=>$('group-editor-dialog').close());closeOnBackdropClick($('group-editor-dialog'));
  addEventListener('gameshelf:create-guardian-profile',event=>{setTimeout(async()=>{try{if(!$('profiles-dialog').open)await openManager();await editProfile(null,true,event.detail.guardianID);}catch(error){notifyError(error);}},typeof motionDuration==='function'?motionDuration(200):200);});
  function confirmRemove(message,payload){pendingRemoval=payload;$('profile-remove-title').textContent=payload.operation.startsWith('reset')?'Reset Role?':'Remove Item?';$('profile-remove-confirm').textContent=payload.operation.startsWith('reset')?'Reset':'Remove';$('profile-remove-question').textContent=message+' This cannot be undone.';openModal($('profile-remove-dialog'));}
  $('profile-remove-confirm').addEventListener('click',async()=>{const save=$('profile-remove-confirm');save.disabled=true;try{const action=pendingRemoval;await post(action);await reloadManagement();$('profile-remove-dialog').close();if(action.operation==='resetRole'){editRole(management.roles[action.role.id]);showNotification('Role reset to its defaults.');}else if(action.operation==='resetGroup'){editGroup(management.profileGroups[action.group.id]);showNotification('Group reset to its defaults.');}else showNotification('Removed.');}catch(error){notifyError(error);}finally{save.disabled=false;}});
  for(const id of ['profile-remove-close','profile-remove-cancel'])$(id).addEventListener('click',()=>$('profile-remove-dialog').close());
  for(const id of ['profiles-dialog','profile-editor-dialog','role-editor-dialog','profile-remove-dialog'])closeOnBackdropClick($(id));
  $('profile-admin-save').addEventListener('click',()=>{editing.adminApproved=true;$('profile-admin-warning').close();saveEditedProfile();});$('profile-admin-create-pin').addEventListener('click',()=>{$('profile-admin-warning').close();editing.pinPreference=true;editing.adminApproved=false;syncProfilePIN();setTimeout(()=>$('profile-new-pin').focus({preventScroll:true}),typeof motionDuration==='function'?motionDuration(180):180);});for(const id of ['profile-admin-close','profile-admin-cancel'])$(id).addEventListener('click',()=>$('profile-admin-warning').close());closeOnBackdropClick($('profile-admin-warning'));
 $('profile-remove-pin').addEventListener('click',()=>{if($('profile-guardian-pin').checked){openGuardianRemoval(false,editing.guardianID);return;}editing.hasSavedPIN=false;editing.pinPreference=false;$('profile-require-pin').checked=false;syncProfilePIN();});$('profile-reset-pin').addEventListener('click',()=>{if($('profile-guardian-pin').checked){GameShelfAccess.openPIN($('profile-guardian-select').value);return;}editing.resetPIN=true;editing.pinPreference=true;syncProfilePIN();$('profile-new-pin').focus({preventScroll:true});});
 let selfEditing=null;
 async function openSelfEditor(profile,alreadyApproved=false){try{if(!alreadyApproved){let result;const open=async pin=>{result=await request('/api/profiles/self/open',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:profile.id,pin})});};if(profile.pinRequired===false)await open('');else if(!await GameShelfAccess.promptPIN(profile.nickname,open))return;}const info=await request('/api/profiles/self');selfEditing={...info.profile,changeOnly:info.changeOnly};$('profile-self-title').textContent=info.changeOnly?'Choose a New PIN':'Profile Information';$('profile-self-identity').hidden=info.changeOnly;$('profile-self-name').value=selfEditing.nickname;selfPhoto(selfEditing.avatar);$('profile-self-pin').value='';$('profile-self-confirm').value='';openModal($('profile-self-dialog'));}catch(error){notifyError(error);}}
 $('profile-self-photo').addEventListener('click',async()=>{const chosen=await GameShelfAvatars.choose(selfEditing.avatar,{guardian:(selfEditing.effectiveRoles||selfEditing.roles).includes('administrator')});if(chosen!==null){selfEditing.avatar=chosen;selfEditing.clearAvatar=chosen==='';selfPhoto(chosen);}});
 $('profile-self-save').addEventListener('click',async()=>{const save=$('profile-self-save'),pin=$('profile-self-pin').value;save.disabled=true;try{await request('/api/profiles/self',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({nickname:$('profile-self-name').value,avatar:selfEditing.avatar||'',clearAvatar:!!selfEditing.clearAvatar,newPIN:pin,confirmPIN:$('profile-self-confirm').value})});const profile={...selfEditing};$('profile-self-dialog').close();showNotification('Profile information saved.');if(profile.changeOnly)await loginProfile(profile,pin);else {state=await request('/api/profiles');required=state.needsProfile;if(required)clearIdentityState();renderPicker(!required);}}catch(error){notifyError(error);}finally{save.disabled=false;}});
 for(const id of ['profile-self-close','profile-self-cancel'])$(id).addEventListener('click',()=>$('profile-self-dialog').close());$('profile-self-dialog').addEventListener('close',()=>{$('profile-self-pin').value='';$('profile-self-confirm').value='';});closeOnBackdropClick($('profile-self-dialog'));
 const originalFetch=window.fetch;
  window.fetch=async(...args)=>{
    const response=await originalFetch(...args);
    if(response.status===401){let result;try{result=await response.clone().json();}catch{/* Not an access response. */}if(result?.code==='profile_required'){clearIdentityState();initialize().catch(notifyError);}}
    return response;
  };
